6	/// An app's own settings page, served by the app process itself.
7	///
8	/// A web view rather than a native screen, and that is forced rather than
9	/// chosen: the daemon exposes no route for any of an app's own configuration —
10	/// `extra["custom_app_url"]` names a port and nothing else — so every app's
11	/// settings live behind a page it renders. A native screen could only be built
12	/// against Conversation App 1.0's `/rpc` (`personalities.*`, `voices.*`,
13	/// `backend.config`) and would leave every other app with no settings at all.
14	///
15	/// The only `WKWebView` in the app. `WebAuthenticationBrowser` is not one — that
16	/// is `ASWebAuthenticationSession`, which runs out of process precisely so this
17	/// app never holds a Hugging Face credential in a web view.
18	struct AppSettingsScreen: View {
19	    /// What the page is doing. `ready` carries nothing because the web view is
20	    /// the whole of it.
21	    enum Phase: Equatable {
22	        case loading
23	        case ready
24	        /// The reason as WebKit gave it — a runtime string, so it stays a
25	        /// `String` rather than becoming a resource (project rule 9).
26	        case failed(String)
27	    }
28	
29	    let url: URL
30	
31	    @State private var phase: Phase
32	    /// Bumped by Try Again. The `switch` below already tears the web view down on
33	    /// a failure, so a retry gets a fresh one either way — but a web view that
34	    /// survived would sit on `loadedURL == url` and quietly do nothing, and a
35	    /// button that silently does nothing is the worse failure.
36	    @State private var attempt = 0
37	    @Environment(\.reachyPreviewMode) private var previewMode
38	
39	    /// `phase` is injectable for the same reason every other screen here takes a
40	    /// frozen model: a preview must be final on its first frame.
41	    init(url: URL, phase: Phase = .loading) {
42	        self.url = url
43	        _phase = State(initialValue: phase)
44	    }
45	
46	    var body: some View {
47	        content
48	            .navigationTitle(.reachy("Settings"))
49	            #if os(iOS)
50	                .navigationBarTitleDisplayMode(.inline)
51	            #endif
52	    }
53	
54	    @ViewBuilder
55	    private var content: some View {
56	        switch phase {
57	        case let .failed(reason):
58	            ContentUnavailableView {
59	                Label(.reachy("Settings unavailable"), systemImage: "wifi.exclamationmark")
60	            } description: {
61	                Text(reason)
62	            } actions: {
63	                Button(.reachy("Try again")) {
64	                    attempt += 1
65	                    phase = .loading
66	                }
67	            }
68	        case .loading, .ready:
69	            page
70	                .contentLoading(isPresented: phase == .loading, title: .reachy("Loading settings…"))
71	        }
72	    }
73	
74	    /// Nothing at all under `reachyPreviewMode`: a preview must not dial an
75	    /// address that does not exist while the image is being captured. It also
76	    /// makes `.ready` render empty, which is honest — see the note on coverage in
77	    /// `AppSettingsPreviews`.
78	    @ViewBuilder
79	    private var page: some View {
80	        if previewMode {
81	            Color.clear
82	        } else {
83	            AppSettingsWebView(url: url, phase: $phase)
84	                .id(attempt)
85	                .ignoresSafeArea(edges: .bottom)
86	        }
87	    }
88	}
89	
90	/// `WKWebView` behind whichever representable the platform has.
91	///
92	/// Written by hand because SwiftUI's own `WebView` is iOS 26 / macOS 26 and this
93	/// app's floor is iOS 18 / macOS 15.
94	private struct AppSettingsWebView {
95	    let url: URL
96	    @Binding var phase: AppSettingsScreen.Phase
97	
98	    @MainActor
99	    final class Coordinator: NSObject, WKNavigationDelegate {
100	        var phase: Binding<AppSettingsScreen.Phase>?
101	        /// What this web view was last asked to load. Without it every SwiftUI
102	        /// update reloads the page, and the page is a form someone is filling in.
103	        var loadedURL: URL?
104	
105	        func webView(_: WKWebView, didFinish _: WKNavigation!) {
106	            phase?.wrappedValue = .ready
107	        }
108	
109	        func webView(_: WKWebView, didFail _: WKNavigation!, withError error: any Error) {
110	            report(error)
111	        }
112	
113	        func webView(_: WKWebView, didFailProvisionalNavigation _: WKNavigation!, withError error: any Error) {
114	            report(error)
115	        }
116	
117	        /// A cancelled navigation is not a failure — it is a load being replaced
118	        /// by the next one, and it arrives as `NSURLErrorCancelled`, whose whole
119	        /// localized description is the word "cancelled". Printing that under
120	        /// "Settings unavailable" is the same bug `RobotSession.message(for:)`
121	        /// exists to prevent, so the check is by code and never by text.
122	        private func report(_ error: any Error) {
123	            guard !RobotSession.isCancellation(error) else { return }
124	            phase?.wrappedValue = .failed(RobotSession.describe(error))
125	        }
126	    }
127	
128	    @MainActor
129	    private func makeWebView(_ coordinator: Coordinator) -> WKWebView {
130	        let webView = WKWebView()
131	        webView.navigationDelegate = coordinator
132	        // The page is the app's own and carries no history the user can reach by
133	        // any other route, so a swipe back would leave them on a blank web view
134	        // with no way forward. Navigation belongs to the sheet around it.
135	        webView.allowsBackForwardNavigationGestures = false
136	        return webView
137	    }
138	
139	    @MainActor
140	    private func load(into webView: WKWebView, _ coordinator: Coordinator) {
141	        coordinator.phase = $phase
142	        guard coordinator.loadedURL != url else { return }
143	        coordinator.loadedURL = url
144	        webView.load(URLRequest(url: url))
145	    }
146	
147	    /// `@MainActor` because `Coordinator` is — the representable protocols isolate
148	    /// this requirement to the main actor, but a nonisolated witness would satisfy
149	    /// them and then fail to construct one.
150	    @MainActor
151	    func makeCoordinator() -> Coordinator {
152	        Coordinator()
153	    }
154	}
155	
156	#if os(iOS)
157	    extension AppSettingsWebView: UIViewRepresentable {
158	        func makeUIView(context: Context) -> WKWebView {
159	            makeWebView(context.coordinator)
160	        }
161	
162	        func updateUIView(_ webView: WKWebView, context: Context) {
163	            load(into: webView, context.coordinator)
164	        }
165	    }
166	#else
167	    extension AppSettingsWebView: NSViewRepresentable {
168	        func makeNSView(context: Context) -> WKWebView {
169	            makeWebView(context.coordinator)
170	        }
171	
172	        func updateNSView(_ webView: WKWebView, context: Context) {
173	            load(into: webView, context.coordinator)
174	        }
175	    }
176	#endif
