3	/// The robot's two maintenance actions. Both of them delete something, and
4	/// neither can be undone from this app.
5	///
6	/// `POST /cache/clear-hf` and `POST /cache/reset-apps`, from
7	/// `daemon/app/routers/cache.py`. Mounted at the **app root** — no `/api` — and
8	/// only when the daemon was started with `--wireless-version`, exactly like
9	/// `/wifi/*` and `/update/*`. The committed OpenAPI spec is generated without
10	/// that flag, so the generated client cannot reach either one and both are
11	/// hand-written here. A Lite robot 404s, which `wirelessData` turns into
12	/// ``ReachyKitError/wirelessFeaturesUnavailable``.
13	///
14	/// Each route answers 200 whether it deleted anything or found the directory
15	/// already gone, and 500 with a `detail` otherwise. The distinction between
16	/// "cleared" and "was already empty" lives only in an English `message` the
17	/// daemon composes, so it is dropped here rather than shown: the outcome is the
18	/// same either way, and a screen cannot translate it.
19	public protocol CacheMaintenanceClient: Sendable {
20	    /// Deletes `/home/pollen/.cache/huggingface` — every model weight the robot
21	    /// has downloaded. They come back on demand, at the cost of the download.
22	    func clearHuggingFaceCache() async throws
23	
24	    /// Deletes `/venvs/apps_venv/` in one `shutil.rmtree`: every installed app
25	    /// **and** the Python environment they share.
26	    ///
27	    /// The daemon does not stop a running app first and does not put anything
28	    /// back — a process left running is a process whose interpreter has been
29	    /// deleted out from under it. Callers are responsible for both.
30	    func resetApps() async throws
31	}
32	
33	extension RobotConnection: CacheMaintenanceClient {
34	    public func clearHuggingFaceCache() async throws {
35	        try await wirelessData(method: "POST", path: "/cache/clear-hf")
36	    }
37	
38	    public func resetApps() async throws {
39	        try await wirelessData(method: "POST", path: "/cache/reset-apps")
40	    }
41	}
42	
43	public extension RobotSession {
44	    /// False on a Lite robot and over the relay, neither of which mounts
45	    /// `/cache/*`.
46	    var canPerformMaintenance: Bool {
47	        client is any CacheMaintenanceClient && supportsWirelessFeatures
48	    }
49	
50	    func clearHuggingFaceCache() async throws {
51	        try await withMaintenanceClient { try await $0.clearHuggingFaceCache() }
52	    }
53	
54	    /// Uninstalls every app. See ``CacheMaintenanceClient/resetApps()`` for what
55	    /// the daemon does *not* do around it.
56	    func resetApps() async throws {
57	        try await withMaintenanceClient { try await $0.resetApps() }
58	    }
59	}
60	
61	extension RobotSession {
62	    func withMaintenanceClient<T>(_ call: (any CacheMaintenanceClient) async throws -> T) async throws -> T {
63	        guard let client else { throw ReachyKitError.notConnected }
64	        guard let maintenance = client as? any CacheMaintenanceClient else {
65	            throw ReachyKitError.wirelessFeaturesUnavailable
66	        }
67	        return try await call(maintenance)
68	    }
69	}
